class Solution:
    def evalRPN(self, tokens: List[str]) -> int:
        stack = []
        ops = set(["+", "-", "*", "/"])

        for token in tokens:
            if token in ops and len(stack) >= 2:
                a = stack.pop()
                b = stack.pop()
                if token == "+":
                    stack.append(a + b)
                elif token == "-":
                    stack.append(b - a)
                elif token == "*":
                    stack.append(a * b)
                elif token == "/":
                    stack.append(int(b / a))
            else:
                stack.append(int(token))

        return stack[-1]
